function Primes(m, n: integer): List<integer>;
begin
  var ls := ubPrimeDivs;
  if m > n then Swap(m, n);
  Result := [];
  if m <= LPrimes[^1] then
  begin
    foreach var prime in LPrimes do
    begin
      if prime > n then break;
      if prime >= m then Result.Add(prime)
    end;
    if Result.Count = 0 then exit;
    m := Result[^1] + 1;
    if m >= n then exit
  end;  
  var ls64: int64 := ls;
  var ln := Ceil(m / ls);
  var rn := Ceil(n / ls);
  for var sn := ln to rn do
  begin
    var a := Max((sn - 1) * ls64 + 1, 2);
    var b := sn * ls64;
    var Sieve := new boolean[ls];
    for var i := 0 to LPrimes.Count - 1 do
    begin
      var prime := LPrimes[i];
      if Sqr(prime) > b then break;
      var k := a;
      var d := k mod prime;
      if d <> 0 then k += prime - d;
      while k <= b do
      begin
        Sieve[integer(k - a)] := True;
        k += prime
      end
    end;
    for var i := 0 to Sieve.High do
      if not Sieve[i] then
        if (a + i >= m) and (a + i <= n) then
          Result.Add(a + i)
  end
end;

